contract Mai is Context, AccessControlEnumerable, ERC20Capped, ERC20Burnable {

    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    constructor() ERC20("Matrix DAO", "MAI") ERC20Capped(1000_0000_0000e18) {
        _setupRole(DEFAULT_ADMIN_ROLE, _msgSender());
        _setupRole(MINTER_ROLE, _msgSender());
    }

    function mint(address to, uint256 amount) external {
        require(hasRole(MINTER_ROLE, _msgSender()), "ERC20: Must have minter role to mint");
        ERC20Capped._mint(to, amount);
    }

    function _mint(address to, uint256 amount) internal override(ERC20, ERC20Capped) {
        super._mint(to,amount);
    }

}

